<?php

namespace App\Mail;

use Illuminate\Http\Client\ConnectionException;
use Illuminate\Http\Client\PendingRequest;
use Illuminate\Support\Facades\Http;
use RuntimeException;

/**
 * Publishes only LONGOS-owned outbound-mail DNS records.
 *
 * DKIM is updated because its selector and key are generated by this stack.
 * Existing SPF and DMARC policies are deliberately preserved: merging an
 * operator's policy without knowing every sender would risk breaking mail
 * from other systems. Caddy certificates are never managed here.
 */
class CloudflareMailDnsService
{
    /** @var array<string, array{id: string, name: string}> */
    private array $zones = [];

    public function __construct(private readonly ?string $tokenOverride = null) {}

    public function configured(): bool
    {
        return (bool) config('mail.relay.auto_configure_dns', true)
            && $this->apiToken() !== '';
    }

    /**
     * Return public DNS values that an operator may safely copy from the
     * administration panel. The relay writes only its public DKIM value to
     * the shared read-only volume; its private key is never available here.
     *
     * @return array<int, array{type: string, name: string, value: string, mode: string, available: bool}>
     */
    public function expectedRecords(): array
    {
        $domains  = $this->signingDomains();
        $selector = strtolower(trim((string) config('mail.relay.dkim_selector', 'mail2026')));
        if ($domains === [] || ! preg_match('/^[a-z0-9][a-z0-9_-]{0,62}$/D', $selector)) {
            return [];
        }

        $records = [];
        foreach ($domains as $domain) {
            try {
                $dkimValue = $this->readDkimValue($domain, $selector);
            } catch (RuntimeException) {
                $dkimValue = '';
            }

            $records[] = [
                'type'      => 'TXT',
                'name'      => "{$selector}._domainkey.{$domain}",
                'value'     => $dkimValue,
                'mode'      => 'managed',
                'available' => $dkimValue !== '',
            ];
            $records[] = [
                'type'      => 'TXT',
                'name'      => $domain,
                'value'     => 'v=spf1 a:' . $this->mailHostname() . ' -all',
                'mode'      => 'if_missing',
                'available' => true,
            ];
            $records[] = [
                'type'      => 'TXT',
                'name'      => "_dmarc.{$domain}",
                'value'     => 'v=DMARC1; p=none',
                'mode'      => 'if_missing',
                'available' => true,
            ];
        }

        $hostname = $this->mailHostname();
        foreach ($this->explicitIpTargets() as $target) {
            $records[] = [
                'type'      => filter_var($target, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6) ? 'AAAA' : 'A',
                'name'      => $hostname,
                'value'     => $target,
                'mode'      => 'managed',
                'available' => true,
            ];
        }

        return $records;
    }

    /**
     * @return array{created: array<int, string>, updated: array<int, string>, preserved: array<int, string>, warnings: array<int, string>}
     */
    public function sync(): array
    {
        if (! $this->configured()) {
            throw new RuntimeException('Cloudflare 邮件 DNS 自动化未启用或未配置 API Token。');
        }

        $domains  = $this->signingDomains();
        $selector = strtolower(trim((string) config('mail.relay.dkim_selector', 'mail2026')));
        if ($domains === [] || ! preg_match('/^[a-z0-9][a-z0-9_-]{0,62}$/D', $selector)) {
            throw new RuntimeException('MAIL_RELAY_DOMAINS 或 MAIL_RELAY_DKIM_SELECTOR 配置无效。');
        }

        $result = ['created' => [], 'updated' => [], 'preserved' => [], 'warnings' => []];
        foreach ($domains as $domain) {
            $dkimName  = "{$selector}._domainkey.{$domain}";
            $dkimValue = $this->readDkimValue($domain, $selector);
            // Confirm the relay has published its public key before making
            // any external API request. On first boot the web container may
            // win the startup race; the scheduler can then retry cleanly
            // without a partial DNS update.
            $zone = $this->resolveZone($domain);

            $this->ensureOwnedRecord($zone['id'], 'TXT', $dkimName, $dkimValue, $result);
            $this->ensurePolicyWhenMissing(
                $zone['id'],
                $domain,
                'v=spf1',
                'v=spf1 a:' . $this->mailHostname() . ' -all',
                $result,
            );
            $this->ensurePolicyWhenMissing(
                $zone['id'],
                "_dmarc.{$domain}",
                'v=dmarc1',
                'v=DMARC1; p=none',
                $result,
            );
        }

        $this->syncMailHostname($result);

        return $result;
    }

    /** @return array<int, string> */
    private function signingDomains(): array
    {
        $domains = config('mail.relay.domains', '');

        return array_values(array_unique(array_filter(array_map(
            static function (mixed $domain): string {
                $domain = strtolower(trim((string) $domain, " .\t\n\r\0\x0B"));

                return self::validPublicDomain($domain)
                    ? $domain
                    : '';
            },
            is_array($domains) ? $domains : explode(',', (string) $domains),
        ))));
    }

    private function mailHostname(): string
    {
        $hostname = strtolower(trim((string) config('mail.relay.hostname'), " .\t\n\r\0\x0B"));
        if (! self::validPublicDomain($hostname)) {
            throw new RuntimeException('MAIL_RELAY_HOSTNAME 不是有效的 DNS 主机名。');
        }

        return $hostname;
    }

    /** @return array{id: string, name: string} */
    private function resolveZone(string $domain): array
    {
        $labels = explode('.', $domain);
        for ($index = 0, $last = count($labels) - 1; $index < $last; $index++) {
            $candidate = implode('.', array_slice($labels, $index));
            if (isset($this->zones[$candidate])) {
                return $this->zones[$candidate];
            }

            $zones = $this->api('GET', '/zones', [
                'name'     => $candidate,
                'status'   => 'active',
                'per_page' => 50,
            ]);
            foreach ($zones as $zone) {
                if (! is_array($zone)
                    || strtolower((string) ($zone['name'] ?? '')) !== $candidate
                    || trim((string) ($zone['id'] ?? '')) === '') {
                    continue;
                }

                return $this->zones[$candidate] = [
                    'id'   => (string) $zone['id'],
                    'name' => $candidate,
                ];
            }
        }

        throw new RuntimeException("Cloudflare Token 无法访问发件域 {$domain} 所在的活动 Zone。");
    }

    private function readDkimValue(string $domain, string $selector): string
    {
        $root = rtrim((string) config('mail.relay.dns_records_path', '/var/lib/longos-mail-dns'), '/\\');
        if ($root === '' || ! is_dir($root)) {
            throw new RuntimeException('邮件中继尚未生成可发布的 DKIM 记录，系统将在下一次调度时重试。');
        }

        $rootReal = realpath($root);
        $path     = $root . DIRECTORY_SEPARATOR . $domain . DIRECTORY_SEPARATOR . $selector . '.txt';
        $pathReal = realpath($path);
        if ($rootReal === false || $pathReal === false
                                || ! str_starts_with($pathReal, $rootReal . DIRECTORY_SEPARATOR)
                                || ! is_file($pathReal) || is_link($path) || ! is_readable($pathReal)) {
            throw new RuntimeException("找不到 {$domain} 的 DKIM 公钥，系统将在邮件中继就绪后自动重试。");
        }

        $value = trim((string) file_get_contents($pathReal));
        if (strlen($value) > 4096
            || ! preg_match('/^v=DKIM1;.*(?:^|;\s*)p=[A-Za-z0-9+\/=]+/i', $value)) {
            throw new RuntimeException("{$domain} 的 DKIM 公钥文件格式无效。");
        }

        return $value;
    }

    /**
     * @param array{created: array<int, string>, updated: array<int, string>, preserved: array<int, string>, warnings: array<int, string>} $result
     */
    private function ensureOwnedRecord(string $zoneId, string $type, string $name, string $content, array &$result): void
    {
        $records = $this->records($zoneId, $type, $name);
        if (count($records) > 1) {
            throw new RuntimeException("Cloudflare 中 {$name} 存在多条 {$type} 记录，为避免覆盖人工配置已停止同步。");
        }

        $payload = [
            'type'    => $type,
            'name'    => $name,
            'content' => $content,
            'ttl'     => 1,
            'proxied' => false,
        ];
        if ($records === []) {
            $this->api('POST', "/zones/{$zoneId}/dns_records", $payload);
            $result['created'][] = "{$type} {$name}";

            return;
        }

        $record = $records[0];
        if (trim((string) ($record['content'] ?? ''), '"') === trim($content, '"')
            && ! (bool) ($record['proxied'] ?? false)) {
            $result['preserved'][] = "{$type} {$name}";

            return;
        }

        $recordId = trim((string) ($record['id'] ?? ''));
        if ($recordId === '') {
            throw new RuntimeException("Cloudflare 返回的 {$name} 记录缺少 ID。");
        }
        $this->api('PUT', "/zones/{$zoneId}/dns_records/{$recordId}", $payload);
        $result['updated'][] = "{$type} {$name}";
    }

    /**
     * @param array{created: array<int, string>, updated: array<int, string>, preserved: array<int, string>, warnings: array<int, string>} $result
     */
    private function ensurePolicyWhenMissing(
        string $zoneId,
        string $name,
        string $prefix,
        string $content,
        array &$result,
    ): void {
        $records  = $this->records($zoneId, 'TXT', $name);
        $policies = array_values(array_filter(
            $records,
            static fn (array $record): bool => str_starts_with(
                strtolower(trim((string) ($record['content'] ?? ''), ' "')),
                strtolower($prefix),
            ),
        ));
        if ($policies !== []) {
            $result['preserved'][] = "TXT {$name}";
            if (count($policies) > 1) {
                $result['warnings'][] = "{$name} 存在多条 {$prefix} 策略；LONGOS 已保留现状，请在 DNS 服务商中合并为单条记录。";
            }

            return;
        }

        if ($records !== []) {
            $result['warnings'][] = "{$name} 已存在其他 TXT 记录；LONGOS 只新增缺失的 {$prefix} 策略，不覆盖现有内容。";
        }
        $this->api('POST', "/zones/{$zoneId}/dns_records", [
            'type'    => 'TXT',
            'name'    => $name,
            'content' => $content,
            'ttl'     => 1,
            'proxied' => false,
        ]);
        $result['created'][] = "TXT {$name}";
    }

    /**
     * @param array{created: array<int, string>, updated: array<int, string>, preserved: array<int, string>, warnings: array<int, string>} $result
     */
    private function syncMailHostname(array &$result): void
    {
        $hostname = $this->mailHostname();
        $targets  = $this->explicitIpTargets();
        if ($targets === []) {
            $result['warnings'][] = 'MAIL_RELAY_IPS 未包含明确公网 IP，已跳过邮件主机 A/AAAA 记录；请确保 MAIL_RELAY_HOSTNAME 与服务器 PTR 人工对齐。';

            return;
        }

        $zone = $this->resolveZone($hostname);
        foreach ($targets as $target) {
            $type    = filter_var($target, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6) ? 'AAAA' : 'A';
            $records = $this->records($zone['id'], $type, $hostname);
            $match   = collect($records)->first(
                static fn (array $record): bool => (string) ($record['content'] ?? '') === (string) $target,
            );
            if ($match && ! (bool) ($match['proxied'] ?? false)) {
                $result['preserved'][] = "{$type} {$hostname}";

                continue;
            }

            $payload = [
                'type'    => $type,
                'name'    => $hostname,
                'content' => (string) $target,
                'ttl'     => 1,
                'proxied' => false,
            ];
            if ($match) {
                $recordId = trim((string) ($match['id'] ?? ''));
                if ($recordId === '') {
                    throw new RuntimeException("Cloudflare 返回的 {$hostname} 记录缺少 ID。");
                }
                $this->api('PUT', "/zones/{$zone['id']}/dns_records/{$recordId}", $payload);
                $result['updated'][] = "{$type} {$hostname}";
            } else {
                $this->api('POST', "/zones/{$zone['id']}/dns_records", $payload);
                $result['created'][] = "{$type} {$hostname}";
            }
        }
    }

    /** @return array<int, string> */
    private function explicitIpTargets(): array
    {
        return array_values(array_unique(array_map(
            static fn (mixed $target): string => trim((string) $target),
            array_filter(
                (array) config('mail.relay.public_ips', []),
                static fn (mixed $target): bool => filter_var(
                    trim((string) $target),
                    FILTER_VALIDATE_IP,
                    FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE | FILTER_FLAG_GLOBAL_RANGE,
                ) !== false,
            ),
        )));
    }

    private static function validPublicDomain(string $domain): bool
    {
        return str_contains($domain, '.')
            && filter_var($domain, FILTER_VALIDATE_IP) === false
            && filter_var($domain, FILTER_VALIDATE_DOMAIN, FILTER_FLAG_HOSTNAME) !== false;
    }

    /** @return array<int, array<string, mixed>> */
    private function records(string $zoneId, string $type, string $name): array
    {
        $records = $this->api('GET', "/zones/{$zoneId}/dns_records", [
            'type'     => $type,
            'name'     => $name,
            'per_page' => 100,
        ]);

        return array_values(array_filter($records, 'is_array'));
    }

    /** @return array<mixed> */
    private function api(string $method, string $path, array $payload = []): array
    {
        $method  = strtoupper($method);
        $options = $method === 'GET' ? ['query' => $payload] : ['json' => $payload];
        $client  = $this->client();
        if ($method === 'GET') {
            // Reads are safe to retry. Mutating requests deliberately are
            // not retried: a timeout after Cloudflare accepted a POST must
            // be reconciled by the next idempotent scheduled sync instead of
            // risking a duplicate SPF, DMARC, or address record.
            $client->retry(3, 250, throw: false);
        }

        try {
            $response = $client->send($method, ltrim($path, '/'), $options);
        } catch (ConnectionException $exception) {
            throw new RuntimeException('Cloudflare DNS API 暂时无法连接。', previous: $exception);
        }
        $body     = $response->json();
        if (! $response->successful() || ! is_array($body) || ($body['success'] ?? false) !== true) {
            $message = collect(is_array($body) ? ($body['errors'] ?? []) : [])
                ->pluck('message')
                ->filter('is_string')
                ->implode('; ');

            throw new RuntimeException('Cloudflare DNS API 请求失败'
                . ($message !== '' ? "：{$message}" : "（HTTP {$response->status()}）"));
        }

        return is_array($body['result'] ?? null) ? $body['result'] : [];
    }

    private function client(): PendingRequest
    {
        $base = rtrim((string) config('mail.relay.cloudflare_api_base', 'https://api.cloudflare.com/client/v4'), '/');
        if (app()->environment('production') && $base !== 'https://api.cloudflare.com/client/v4') {
            throw new RuntimeException('Cloudflare API 端点在生产环境必须使用官方 HTTPS 地址。');
        }

        return Http::baseUrl($base . '/')
            ->withToken($this->apiToken())
            ->acceptJson()
            ->asJson()
            ->connectTimeout(5)
            ->timeout(15);
    }

    private function apiToken(): string
    {
        if (is_string($this->tokenOverride) && trim($this->tokenOverride) !== '') {
            return trim($this->tokenOverride);
        }

        $token = trim((string) env('CLOUDFLARE_API_TOKEN', ''));
        if ($token !== '') {
            return $token;
        }

        $path = trim((string) config('longos.cloudflare.api_token_file', ''));
        if ($path === '' || ! @is_file($path) || @is_link($path) || ! @is_readable($path)) {
            return '';
        }

        return trim((string) @file_get_contents($path));
    }
}
